script.setup:
const s=ctx.state,gl=ctx.gl;s.canvas=new OffscreenCanvas(1,1);s.c=s.canvas.getContext('2d');s.texture=gl.createTexture();
s.palette=['#57d8c6','#ffbc78','#ad9bff','#fa7f9c','#9adcfa','#d2e79d'];
s.random=(seed)=>()=>{seed|=0;seed=seed+0x6D2B79F5|0;let t=Math.imul(seed^seed>>>15,1|seed);t=t+Math.imul(t^t>>>7,61|t)^t;return ((t^t>>>14)>>>0)/4294967296;};
s.rand=s.random(17);
s.path=(points,color='#57d8c6',width=.008,closed=false,fill=null)=>{if(!points?.length)return;const c=s.c;c.beginPath();points.forEach((p,i)=>i?c.lineTo(p[0],p[1]):c.moveTo(p[0],p[1]));if(closed)c.closePath();if(fill){c.fillStyle=fill;c.fill('evenodd');}if(width){c.strokeStyle=color;c.lineWidth=width;c.lineJoin='round';c.lineCap='round';c.stroke();}};
s.dot=(p,color='#ffbc78',r=.013)=>{const c=s.c;c.beginPath();c.arc(p[0],p[1],r,0,Math.PI*2);c.fillStyle=color;c.fill();};
s.cloud=Array.from({length:160},(_,i)=>{const t=i*2.39996323,r=.1+.74*Math.sqrt(s.rand());return [Math.cos(t)*r,Math.sin(t)*r*(.5+.4*Math.cos(t)**2)];});
s.wave=Array.from({length:121},(_,i)=>{const x=-.9+i*.015;return [x,.32*Math.sin(x*6)+.085*Math.sin(x*39)];});
s.star=(count=10,outer=.8,inner=.4)=>Array.from({length:count*2},(_,i)=>{const a=i*Math.PI/count-Math.PI/2,r=i%2?inner:outer;return [Math.cos(a)*r,Math.sin(a)*r];});
s.mesh=(points,cells)=>cells.forEach((cell,i)=>s.path(cell.map(n=>points[n]),'#0d1c2f',.005,true,s.palette[i%s.palette.length]));
s.show=ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER,`#version 300 es
precision highp float;in vec2 v_uv;out vec4 outColor;uniform sampler2D u_image;void main(){outColor=texture(u_image,vec2(v_uv.x,1.-v_uv.y));}`);
s.data=await (await fetch(ctx.assets['result.json'])).json();s.labels=["24×24 bins","40×40 bins","64×64 bins"];s.project=(p)=>{const a=ctx.uniforms.u_turn||0,x=p[0],y=p[1],z=p[2]||0;return [(x*Math.cos(a)+z*Math.sin(a))*ctx.uniforms.u_scale,-(y*1+(-x*Math.sin(a)+z*Math.cos(a))*0)*ctx.uniforms.u_scale];};

script.render:
const s=ctx.state,u=ctx.uniforms,c=s.c,gl=ctx.gl,[w,h]=ctx.resolution,m=Math.min(w,h);if(s.canvas.width!==w||s.canvas.height!==h){s.canvas.width=w;s.canvas.height=h;}c.fillStyle='#0b1625';c.fillRect(0,0,w,h);c.save();c.translate(w/2,h/2);c.scale(m*.42,m*.42);for(let i=-10;i<=10;i++){s.path([[-1,i/10],[1,i/10]],'#17273a',.002);s.path([[i/10,-1],[i/10,1]],'#17273a',.002);}const key=JSON.stringify(u);
const f=s.data.frames[Math.min(s.data.frames.length-1,Math.max(0,Math.round(u.u_frame)))];
if(f.mesh){const pts=f.mesh.vertices,projected=pts.map(s.project);const faces=f.mesh.faces.slice().sort((a,b)=>{const depth=(cell)=>cell.reduce((v,i)=>v+pts[i][2]*Math.cos(u.u_turn)-pts[i][0]*Math.sin(u.u_turn),0)/cell.length;return depth(a)-depth(b);});for(const cell of faces){const a=pts[cell[0]],b=pts[cell[1]],d=pts[cell[2]],ab=b.map((v,i)=>v-a[i]),ad=d.map((v,i)=>v-a[i]);const normal=[ab[1]*ad[2]-ab[2]*ad[1],ab[2]*ad[0]-ab[0]*ad[2],ab[0]*ad[1]-ab[1]*ad[0]],light=.3+.7*Math.abs((normal[0]*.2+normal[1]*.6+normal[2]*.8)/(Math.hypot(...normal)||1));s.path(cell.map(i=>projected[i]),'#182e3a',.0015,true,'rgb('+Math.round(70*light)+','+Math.round(210*light)+','+Math.round(190*light)+')');}}
for(const line of f.paths||[])s.path(line.points.map(s.project),line.color||'#57d8c6',.008);
const dots=(f.points||[]).map((p,i)=>({p,i})).sort((a,b)=>(a.p[2]||0)-(b.p[2]||0));for(const {p,i}of dots){const v=f.values?.[i];s.dot(s.project(p),v===undefined?'#ffbc78':'hsl('+Math.round(180+v*85)+' 65% 65%)',f.radius||.018);}
s.note=(s.labels[u.u_frame]||'Prepared frame '+(u.u_frame+1)+' / '+s.data.frames.length)+' · locally computed';c.restore();c.fillStyle='#a9bdd0';c.font=Math.max(11,m*.024)+'px sans-serif';c.textAlign='center';c.fillText(s.note||'',w/2,h*.94);ctx.publish('result',s.note||'ready');
gl.bindTexture(gl.TEXTURE_2D,s.texture);gl.texImage2D(gl.TEXTURE_2D,0,gl.RGBA,gl.RGBA,gl.UNSIGNED_BYTE,s.canvas);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MIN_FILTER,gl.LINEAR);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MAG_FILTER,gl.LINEAR);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_S,gl.CLAMP_TO_EDGE);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_T,gl.CLAMP_TO_EDGE);gl.useProgram(s.show);ctx.utils.bindTexture(s.show,'u_image',s.texture,0);ctx.utils.drawFullscreen(s.show);
